JFrame f = new JFrame("Tip");
JTextField bill = new JTextField(8), pct = new JTextField(8); JLabel out = new JLabel("Total: ");
JButton go = new JButton("Calculate");
go.addActionListener(e -> { try { double b = Double.parseDouble(bill.getText()), p = Double.parseDouble(pct.getText()); out.setText("Total: " + (b + b * p / 100)); } catch (NumberFormatException ex) { JOptionPane.showMessageDialog(f, "Numbers only"); } });
JPanel p = new JPanel(new GridLayout(4, 2)); p.add(new JLabel("Bill:")); p.add(bill); p.add(new JLabel("Tip %:")); p.add(pct); p.add(go); p.add(out);
f.add(p); f.setSize(260, 180); f.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE); f.setVisible(true);
